function parseAIData(dataString) {
    const data = { 选项: [], '想法': '', '正文': '', '日记': '' };
    if (!dataString) return data;

    const lines = dataString.replace(/<\/[^>]+>$/, '').trim().split('\n');
    let currentKey = null;

    const knownKeys = [
        '天数', '每日开销', '当前时间段', '舆论风向', '人气', '收入', '圈内地位', '地位', '合同', '公众形象', '代言等级',
        '时间', '地点', '环境', '事件', '精神状态', '好感度', '对<user>好感度', '压力值', '健康状况',
        '正文', '想法', '日记', 
        '唱功', '舞蹈', '颜值', '魅力', '才智', '体力', 
        '作词', '作曲', '高音爆发', '剧本理解', '情绪控制', '即兴反应'
    ];

    for (const line of lines) {
        const trimmedLine = line.trim();
        if (!trimmedLine) continue;

        const kvMatch = trimmedLine.match(/^([^\n:：]+?)[:：](.*)$/);
        const potentialKey = kvMatch ? kvMatch[1].trim() : null;

        if (potentialKey && (knownKeys.includes(potentialKey) || potentialKey.startsWith('选项'))) {
            currentKey = potentialKey;
            const value = kvMatch[2].trim();

            if (currentKey.startsWith('选项')) {
                if (value) data.选项.push(value);
                currentKey = null;
            } else {
                data[currentKey] = value;
            }
        } else if (currentKey) {
            data[currentKey] += '\n' + trimmedLine;
        }
    }

    // Normalize keys
    if (data['地位'] && !data['圈内地位']) {
        data['圈内地位'] = data['地位'];
    }
    if (data['好感度'] && !data['对<user>好感度']) {
        data['对<user>好感度'] = data['好感度'];
    }

    // Parse thoughts
    if (data['想法']) {
        const thoughtBlock = data['想法'];
        const thoughtRegex = /(?:([^\n(（]+?)\s*[:：]\s*)?[（(]([\s\S]+?)[）)]/g;
        const parsedThoughts = [];
        let match;

        while ((match = thoughtRegex.exec(thoughtBlock)) !== null) {
            let speaker = match[1] ? match[1].trim() : '内心独白';
            let content = match[2].trim();

            const innerSplit = content.split(/[:：]/, 2);
            if (innerSplit.length > 1 && innerSplit[0].length < 20 && !innerSplit[0].includes(' ')) {
                speaker = innerSplit[0].trim();
                content = innerSplit[1].trim();
            }

            if (speaker === '想法') {
                speaker = '内心独白';
            }

            parsedThoughts.push({ speaker: speaker, content: content });
        }
        data.想法 = parsedThoughts;
    } else {
        data.想法 = [];
    }

    return data;
}

function formatMainContent(content) {
if (!content) return '<div class="no-content-message">暂无内容</div>';

const lines = content.split('\n');
let formattedLines = [];

for (let line of lines) {
line = line.trim();
if (!line && formattedLines.length > 0 && formattedLines[formattedLines.length-1] !== '<br>') {
    formattedLines.push('<br>');
    continue;
}
if (!line) continue;


if (line.startsWith('「') && line.endsWith('」')) {
formattedLines.push(`<div class="dialogue-line dialogue-character">${line}</div>`);
} else if (line.includes('：') && (line.includes('「') || line.includes('『'))) {
const parts = line.split('：');
if (parts.length >= 2) {
const speaker = parts[0].trim();
const dialogue = parts.slice(1).join('：').trim();
formattedLines.push(`<div class="dialogue-line dialogue-character"><strong>${speaker}：</strong>${dialogue}</div>`);
} else {
formattedLines.push(`<div class="dialogue-line dialogue-character">${line}</div>`);
}
} else if (line.includes('<user>')) {
formattedLines.push(`<div class="dialogue-line dialogue-user">${line.replace(/<user>/g, '<strong>玩家</strong>')}</div>`);
} else if (line.startsWith('*') && line.endsWith('*')) {
formattedLines.push(`<div class="action-text">${line}</div>`);
} else if (line.startsWith('【') && line.endsWith('】')) {
formattedLines.push(`<div class="dialogue-line dialogue-system">${line}</div>`);
} else if (line.includes('想到') || line.includes('心想') || line.includes('暗想')) {
formattedLines.push(`<div class="dialogue-line dialogue-narrator">${line}</div>`);
} else {
formattedLines.push(`<div class="narrative-text">${line}</div>`);
}
}

return formattedLines.join('');
}

function updateUIFromData(data) {
const setText = (id, value, containerId = null) => {
const element = el(id);
if (element) {
const displayValue = value || '--';
element.textContent = displayValue;
if (containerId && id === 'panel-main-content') {
const container = el(containerId);
if (container) {
container.innerHTML = value ? formatMainContent(value) : `<div class="no-content-message">暂无内容</div>`;
}
} else if (containerId) {
const container = el(containerId);
if (container) container.innerHTML = value ? value.replace(/<user>/g, '<user>') : `<div class="no-content-message">暂无内容</div>`;
}
}
};

setText('panel-main-content', data['正文'], 'panel-main');

// 更新变量面板
setText('var-days', data['天数']);
