.nav-button.active {
color: #ffffff;
background: linear-gradient(135deg, rgba(255, 159, 202, 0.3), rgba(245, 201, 126, 0.2));
border: 2px solid rgba(255, 159, 202, 0.5);
box-shadow: 0 0 20px rgba(255, 159, 202, 0.4);
animation: activeButtonPulse 2s ease-in-out infinite;
}

@keyframes activeButtonPulse {
0%, 100% { box-shadow: 0 0 20px rgba(255, 159, 202, 0.4); }
50% { box-shadow: 0 0 30px rgba(255, 159, 202, 0.6); }
}

.nav-button.active::after {
width: 85%;
}

.content-area {
flex-grow: 1;
padding: clamp(18px, 3.5vw, 26px);
overflow-y: auto;
position: relative;
z-index: 1;
background: var(--content-bg);
}

.content-area::-webkit-scrollbar {
width: 10px;
}

.content-area::-webkit-scrollbar-track {
background: rgba(0, 0, 0, 0.4);
border-radius: 5px;
}

.content-area::-webkit-scrollbar-thumb {
background: linear-gradient(180deg, var(--pink-1), var(--highlight-color));
border-radius: 5px;
border: 2px solid rgba(255, 255, 255, 0.1);
box-shadow: 0 0 10px rgba(255, 159, 202, 0.3);
}

.content-area::-webkit-scrollbar-thumb:hover {
box-shadow: 0 0 15px rgba(255, 159, 202, 0.5);
}

.panel {
display: none;
line-height: 1.9;
font-size: clamp(14px, 2vw, 16px);
}

.panel.active {
display: block;
animation: fadeInSlide 0.8s ease;
}

@keyframes fadeInSlide {
from { 
    opacity: 0; 
    transform: translateY(15px) scale(0.98); 
}
to { 
    opacity: 1; 
    transform: translateY(0) scale(1); 
}
}

/* 主内容面板特殊样式 */
#panel-main-content {
white-space: pre-wrap;
background: linear-gradient(135deg, rgba(0, 0, 0, 0.35) 0%, rgba(55, 45, 85, 0.45) 100%);
padding: clamp(22px, 4.5vw, 32px);
border-radius: 20px;
border: 2px solid rgba(255, 159, 202, 0.3);
box-shadow: 
inset 0 2px 0 rgba(255, 255, 255, 0.08),
0 8px 25px rgba(0, 0, 0, 0.4);
line-height: 2.4;
font-size: clamp(15px, 2.2vw, 17px);
letter-spacing: 0.8px;
}

#panel-main-content .dialogue-line {
margin: 2.5em 0;
padding: 16px 22px;
border-radius: 16px;
border-left: 5px solid;
background: rgba(255, 255, 255, 0.05);
backdrop-filter: blur(8px);
transition: all 0.4s ease;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
animation: dialogueFloat 3s ease-in-out infinite;
}

@keyframes dialogueFloat {
0%, 100% { transform: translateY(0); }
50% { transform: translateY(-3px); }
}

#panel-main-content .dialogue-line:hover {
background: rgba(255, 255, 255, 0.12);
transform: translateX(8px) translateY(-5px);
box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);
}

#panel-main-content .dialogue-user {
color: var(--dialogue-user);
border-left-color: var(--dialogue-user);
background: linear-gradient(135deg, rgba(135, 206, 235, 0.15), rgba(135, 206, 235, 0.05));
}

#panel-main-content .dialogue-system {
color: var(--dialogue-system);
border-left-color: var(--dialogue-system);
background: linear-gradient(135deg, rgba(255, 160, 122, 0.15), rgba(255, 160, 122, 0.05));
}

#panel-main-content .dialogue-character {
color: var(--dialogue-character);
border-left-color: var(--dialogue-character);
background: linear-gradient(135deg, rgba(152, 251, 152, 0.15), rgba(152, 251, 152, 0.05));
}

#panel-main-content .dialogue-narrator {
color: var(--dialogue-narrator);
border-left-color: var(--dialogue-narrator);
background: linear-gradient(135deg, rgba(221, 160, 221, 0.15), rgba(221, 160, 221, 0.05));
}

#panel-main-content .narrative-text {
margin: 2.2em 0;
color: var(--primary-text);
line-height: 2.6;
text-indent: 2em;
padding: 16px 0;
border-bottom: 1px solid rgba(255, 159, 202, 0.1);
}

#panel-main-content .action-text {
margin: 2em 0;
color: var(--secondary-text);
font-style: italic;
opacity: 0.95;
padding: 12px 0 12px 24px;
border-left: 3px solid rgba(255, 159, 202, 0.5);
background: linear-gradient(90deg, rgba(255, 159, 202, 0.08), transparent);
border-radius: 0 12px 12px 0;
}

#panel-main-content br {
display: block;
margin: 1.5em 0;
content: "";
}

#panel-diary-content, #panel-thoughts {
white-space: pre-wrap;
background: linear-gradient(135deg, rgba(0, 0, 0, 0.35) 0%, rgba(55, 45, 85, 0.45) 100%);
padding: clamp(22px, 4.5vw, 28px);
border-radius: 20px;
border: 2px solid rgba(255, 159, 202, 0.3);
box-shadow: 
inset 0 2px 0 rgba(255, 255, 255, 0.08),
0 8px 25px rgba(0, 0, 0, 0.4);
line-height: 2.1;
}

.variable-list, .status-list, .skill-list, .attribute-list {
list-style: none;
}

.variable-list li, .status-list li, .skill-list li, .attribute-list li {
padding: clamp(16px, 3.5vw, 22px);
margin-bottom: 16px;
background: linear-gradient(135deg,
rgba(55, 45, 85, 0.8) 0%,
rgba(40, 30, 60, 0.6) 100%);
border-left: 4px solid var(--pink-1);
border-radius: 16px;
transition: all 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
border: 2px solid rgba(255, 159, 202, 0.2);
box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
position: relative;
overflow: hidden;
animation: listItemFloat 4s ease-in-out infinite;
}

@keyframes listItemFloat {
0%, 100% { transform: translateY(0); }
50% { transform: translateY(-2px); }
}

.variable-list li:nth-child(even), .status-list li:nth-child(even), 
.skill-list li:nth-child(even), .attribute-list li:nth-child(even) {
animation-delay: 2s;
}

.variable-list li::before, .status-list li::before, .skill-list li::before, .attribute-list li::before {
content: '';
position: absolute;
top: 0;
left: 0;
right: 0;
bottom: 0;
background: linear-gradient(45deg, transparent, rgba(255, 159, 202, 0.1), transparent);
opacity: 0;
transition: opacity 0.3s ease;
animation: shimmerEffect 3s ease-in-out infinite;
}

@keyframes shimmerEffect {
0% { transform: translateX(-100%) rotate(45deg); }
100% { transform: translateX(100%) rotate(45deg); }
}

.variable-list li:hover, .status-list li:hover, .skill-list li:hover, .attribute-list li:hover {
transform: translateX(12px) translateY(-4px) scale(1.02);
border-left-color: var(--highlight-color);
box-shadow: 0 12px 35px rgba(0, 0, 0, 0.4), 0 0 30px rgba(255, 159, 202, 0.35);
}

.variable-list li:hover::before, .status-list li:hover::before, .skill-list li:hover::before, .attribute-list li:hover::before {
opacity: 1;
}

.list-item-header {
display: flex;
justify-content: space-between;
align-items: center;
margin-bottom: 12px;
}

.label {
color: var(--secondary-text);
font-size: clamp(13px, 1.8vw, 14px);
font-weight: 400;
text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5);
}

.value {
color: var(--primary-text);
font-weight: 700;
text-shadow: 0 0 15px var(--pink-glow);
font-size: clamp(13px, 1.8vw, 15px);
}

.progress-bar-container {
width: 100%;
height: 16px;
background: linear-gradient(90deg, rgba(0, 0, 0, 0.7), rgba(55, 45, 85, 0.9));
border-radius: 8px;
overflow: hidden;
margin-top: 12px;
border: 2px solid rgba(255, 159, 202, 0.4);
position: relative;
box-shadow: inset 0 3px 6px rgba(0, 0, 0, 0.5);
}

.progress-bar-container::before {
content: '';
position: absolute;
top: 0;
left: 0;
right: 0;
bottom: 0;
background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.15), transparent);
animation: progressShimmer 3.5s infinite;
}

@keyframes progressShimmer {
0% { transform: translateX(-100%); }
100% { transform: translateX(100%); }
}

.progress-bar-fill {
height: 100%;
width: 0;
background: linear-gradient(90deg,
var(--pink-3) 0%,
var(--pink-1) 30%,
var(--accent-color-1) 70%,
var(--highlight-color) 100%);
border-radius: 8px;
transition: width 2s cubic-bezier(0.25, 0.1, 0.25, 1);
box-shadow:
0 0 25px var(--pink-glow),
inset 0 2px 0 rgba(255, 255, 255, 0.4);
position: relative;
overflow: hidden;
}

.progress-bar-fill::after {
content: '';
position: absolute;
top: 0;
left: 0;
right: 0;
bottom: 0;
background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.6), transparent);
animation: progressFlow 3s infinite;
}

@keyframes progressFlow {
0% { transform: translateX(-100%); }
100% { transform: translateX(100%); }
}

.status-list li {
display: flex;
justify-content: space-between;
align-items: center;
}

.status-list .value {
color: var(--pink-2);
font-weight: 600;
text-shadow: 0 0 12px rgba(255, 179, 209, 0.5);
}

/* 成就系统样式 */
.achievements-grid {
display: grid;
grid-template-columns: repeat(auto-fill, minmax(clamp(150px, 22vw, 170px), 1fr));
gap: clamp(14px, 2.5vw, 18px);
padding: 12px;
}

.achievement-card {
background: linear-gradient(135deg, rgba(55, 45, 85, 0.95), rgba(40, 30, 60, 0.8));
border: 3px solid rgba(255, 159, 202, 0.3);
border-radius: 20px;
padding: clamp(18px, 3.5vw, 24px);
text-align: center;
transition: all 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
position: relative;
overflow: hidden;
cursor: pointer;
box-shadow: 0 6px 20px rgba(0, 0, 0, 0.4);
animation: cardFloat 6s ease-in-out infinite;
}

@keyframes cardFloat {
0%, 100% { 
    transform: translateY(0) rotate(0deg); 
    filter: hue-rotate(0deg);
}
25% { 
    transform: translateY(-2px) rotate(0.5deg); 
    filter: hue-rotate(15deg);
}
50% { 
    transform: translateY(-4px) rotate(-0.5deg); 
    filter: hue-rotate(30deg);
}
75% { 
    transform: translateY(-2px) rotate(0.5deg); 
    filter: hue-rotate(15deg);
}
}

.achievement-card:nth-child(even) {
animation-delay: 3s;
}

.achievement-card::before {
content: '';
position: absolute;
top: -50%;
left: -50%;
width: 200%;
height: 200%;
background: radial-gradient(circle, rgba(255, 159, 202, 0.2) 0%, transparent 70%);
transform: rotate(45deg);
transition: all 0.8s ease;
opacity: 0;
animation: cardGlow 8s ease-in-out infinite;
}

@keyframes cardGlow {
0%, 100% { opacity: 0; }
50% { opacity: 0.3; }
}

.achievement-card:hover::before {
opacity: 1;
transform: rotate(45deg) scale(1.8);
}

.achievement-card.unlocked {
background: linear-gradient(135deg, 
rgba(255, 215, 0, 0.2), 
rgba(255, 159, 202, 0.2),
rgba(194, 153, 255, 0.15));
border-width: 3px;
border-style: solid;
border-image-slice: 1;
border-image-source: var(--border-gradient);
animation: achievementUnlock 0.8s ease, cardFloatUnlocked 4s ease-in-out infinite;
}

@keyframes achievementUnlock {
0% { 
    transform: scale(0.7) rotate(-10deg); 
    opacity: 0; 
}
50% { 
    transform: scale(1.15) rotate(10deg); 
}
100% { 
    transform: scale(1) rotate(0deg); 
    opacity: 1; 
}
}

@keyframes cardFloatUnlocked {
0%, 100% { 
    transform: translateY(0);
    box-shadow: 0 8px 25px rgba(0,0,0,0.3), 0 0 25px var(--glow-color);
}
50% { 
    transform: translateY(-5px);
    box-shadow: 0 12px 30px rgba(0,0,0,0.4), 0 0 35px var(--pink-glow);
}
}

.achievement-card:hover {
transform: translateY(-10px) scale(1.08) rotate(2deg);
box-shadow: 0 15px 40px rgba(0, 0, 0, 0.5), 0 0 40px rgba(255, 159, 202, 0.4);
}

.achievement-icon {
font-size: clamp(38px, 6.5vw, 52px);
margin-bottom: 14px;
display: block;
filter: grayscale(100%) opacity(0.6);
transition: all 0.5s ease;
animation: iconPulse 3s ease-in-out infinite;
}

@keyframes iconPulse {
0%, 100% { transform: scale(1); }
50% { transform: scale(1.05); }
}

.achievement-card.unlocked .achievement-icon {
filter: grayscale(0%) opacity(1) drop-shadow(0 0 15px rgba(255, 215, 0, 0.9));
animation: iconBounce 0.8s ease, iconGlow 2s ease-in-out infinite;
}

@keyframes iconBounce {
0%, 100% { transform: translateY(0); }
50% { transform: translateY(-12px); }
}

@keyframes iconGlow {
0%, 100% { 
    filter: grayscale(0%) opacity(1) drop-shadow(0 0 15px rgba(255, 215, 0, 0.9));
}
50% { 
    filter: grayscale(0%) opacity(1) drop-shadow(0 0 25px rgba(255, 159, 202, 0.9));
}
}

.achievement-name {
font-size: clamp(12px, 1.9vw, 15px);
font-weight: 700;
color: var(--secondary-text);
margin-bottom: 8px;
transition: color 0.4s ease;
}

.achievement-card.unlocked .achievement-name {
color: var(--achievement-gold);
text-shadow: 0 0 12px rgba(255, 215, 0, 0.7);
animation: textGlow 2s ease-in-out infinite;
}

@keyframes textGlow {
0%, 100% { text-shadow: 0 0 12px rgba(255, 215, 0, 0.7); }
50% { text-shadow: 0 0 20px rgba(255, 159, 202, 0.8); }
}

.achievement-desc {
font-size: clamp(11px, 1.6vw, 13px);
color: var(--secondary-text);
opacity: 0.85;
line-height: 1.5;
}

.achievement-progress {
margin-top: 10px;
font-size: clamp(10px, 1.5vw, 12px);
color: var(--pink-1);
animation: progressText 4s ease-in-out infinite;
}

@keyframes progressText {
0%, 100% { color: var(--pink-1); }
50% { color: var(--accent-color-1); }
}

/* 多人想法样式 */
.thoughts-container {
display: flex;
flex-direction: column;
gap: 20px;
}

.thought-bubble {
background: linear-gradient(135deg, rgba(255, 159, 202, 0.15), rgba(55, 45, 85, 0.7));
border: 2px solid rgba(255, 159, 202, 0.4);
border-radius: 20px;
padding: clamp(18px, 3.5vw, 24px);
position: relative;
animation: thoughtFloat 5s ease-in-out infinite;
box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
}

.thought-bubble:nth-child(even) {
animation-delay: 2.5s;
background: linear-gradient(135deg, rgba(194, 153, 255, 0.15), rgba(55, 45, 85, 0.7));
border-color: rgba(194, 153, 255, 0.4);
}

@keyframes thoughtFloat {
0%, 100% { 
    transform: translateY(0) rotate(0deg); 
}
33% { 
    transform: translateY(-8px) rotate(0.5deg); 
}
66% { 
    transform: translateY(-4px) rotate(-0.5deg); 
}
}

.thought-speaker {
color: var(--pink-2);
font-weight: 700;
margin-bottom: 10px;
font-size: clamp(13px, 1.9vw, 15px);
text-shadow: 0 0 12px rgba(255, 179, 209, 0.5);
animation: speakerGlow 3s ease-in-out infinite;
}

@keyframes speakerGlow {
0%, 100% { text-shadow: 0 0 12px rgba(255, 179, 209, 0.5); }
50% { text-shadow: 0 0 18px rgba(245, 201, 126, 0.6); }
}

.thought-content {
color: var(--primary-text);
line-height: 1.8;
white-space: pre-wrap;
}

/* 选项样式优化 */
.options-container {
display: grid;
grid-template-columns: 1fr;
gap: 18px;
}

.option-button {
background: linear-gradient(135deg,
rgba(255, 159, 202, 0.22) 0%,
rgba(55, 45, 85, 0.5) 100%);
border: 3px solid rgba(255, 159, 202, 0.4);
color: var(--primary-text);
padding: clamp(18px, 3.5vw, 22px) clamp(22px, 4.5vw, 28px);
text-align: left;
border-radius: 18px;
cursor: pointer;
transition: all 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
font-family: inherit;
font-size: clamp(13px, 1.9vw, 15px);
position: relative;
overflow: hidden;
box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
animation: optionPulse 4s ease-in-out infinite;
}

@keyframes optionPulse {
0%, 100% { 
    transform: scale(1);
    border-color: rgba(255, 159, 202, 0.4);
}
50% { 
    transform: scale(1.01);
    border-color: rgba(194, 153, 255, 0.4);
}
}

.option-button::before {
content: '';
position: absolute;
top: 0;
left: -100%;
width: 100%;
height: 100%;
background: linear-gradient(90deg, transparent, rgba(255, 159, 202, 0.2), transparent);
transition: left 0.6s ease;
}

.option-button:hover {
background: linear-gradient(135deg,
rgba(255, 159, 202, 0.35) 0%,
rgba(245, 201, 126, 0.22) 100%);
border-color: var(--pink-2);
transform: translateY(-5px) scale(1.02);
box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4), 0 0 25px rgba(255, 159, 202, 0.3);
animation: none;
}

.option-button:hover::before {
left: 100%;
}

.option-button:active {
transform: translateY(-2px);
box-shadow: 0 6px 15px rgba(0, 0, 0, 0.4);
}

.option-button::after {
content: '💖';
position: absolute;
right: 22px;
top: 50%;
transform: translateY(-50%);
opacity: 0;
transition: opacity 0.4s ease;
font-size: clamp(16px, 2.2vw, 18px);
animation: heartBeat 2s ease-in-out infinite;
}

@keyframes heartBeat {
0%, 100% { transform: translateY(-50%) scale(1); }
50% { transform: translateY(-50%) scale(1.1); }
}

.option-button:hover::after {
opacity: 1;
}

.diary-entry {
background: linear-gradient(135deg, rgba(0, 0, 0, 0.45), rgba(55, 45, 85, 0.4));
padding: clamp(18px, 3.5vw, 24px);
margin-bottom: 20px;
border-radius: 18px;
border-left: 5px solid var(--pink-1);
border: 2px solid rgba(255, 159, 202, 0.3);
box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
animation: diaryGlow 6s ease-in-out infinite;
}

@keyframes diaryGlow {
0%, 100% { 
    border-color: rgba(255, 159, 202, 0.3);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
}
50% { 
    border-color: rgba(194, 153, 255, 0.4);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.4);
}
}

.diary-header {
color: var(--pink-2);
font-weight: 700;
margin-bottom: 14px;
text-shadow: 0 0 12px rgba(255, 179, 209, 0.5);
font-size: clamp(14px, 2.2vw, 17px);
animation: headerShine 4s ease-in-out infinite;
}

@keyframes headerShine {
0%, 100% { text-shadow: 0 0 12px rgba(255, 179, 209, 0.5); }
50% { text-shadow: 0 0 18px rgba(245, 201, 126, 0.6); }
}

.no-content-message {
color: var(--secondary-text);
text-align: center;
padding: clamp(28px, 5.5vw, 36px);
background: linear-gradient(135deg, rgba(0, 0, 0, 0.35), rgba(55, 45, 85, 0.3));
border-radius: 20px;
border: 2px dashed rgba(255, 159, 202, 0.4);
font-size: clamp(14px, 2.2vw, 17px);
animation: messagePulse 5s ease-in-out infinite;
}

@keyframes messagePulse {
0%, 100% { 
    border-color: rgba(255, 159, 202, 0.4);
    transform: scale(1);
}
50% { 
    border-color: rgba(194, 153, 255, 0.5);
    transform: scale(1.01);
}
}

/* 成就解锁通知 */
.achievement-notification {
position: fixed;
top: 25px;
right: 25px;
background: linear-gradient(135deg, rgba(255, 215, 0, 0.98), rgba(255, 159, 202, 0.98));
color: #1a0f2e;
padding: 20px 28px;
border-radius: 16px;
box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
transform: translateX(450px);
transition: transform 0.6s cubic-bezier(0.25, 0.1, 0.25, 1);
z-index: 1000;
font-weight: 700;
font-size: clamp(13px, 1.9vw, 15px);
border: 2px solid rgba(255, 215, 0, 0.8);
animation: notificationGlow 2s ease-in-out infinite;
}

@keyframes notificationGlow {
0%, 100% { 
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5), 0 0 20px rgba(255, 215, 0, 0.5);
}
50% { 
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5), 0 0 30px rgba(255, 159, 202, 0.6);
}
}

.achievement-notification.show {
transform: translateX(0);
animation: notificationShow 0.6s ease, notificationGlow 2s ease-in-out infinite;
}

@keyframes notificationShow {
0% { transform: translateX(450px) rotate(10deg); }
100% { transform: translateX(0) rotate(0deg); }
}

/* 移动端优化 */
@media (max-width: 768px) {
body {
padding: 8px;
}

.main-container {
height: 95vh;
max-width: 98vw;
border-radius: 20px;
}

.nav-bar {
padding: 10px 6px;
gap: 4px;
}

.nav-button {
padding: 10px 8px;
min-width: 55px;
max-width: 85px;
}

.content-area {
padding: 16px;
}

.variable-list li, .status-list li, .skill-list li, .attribute-list li {
padding: 14px;
margin-bottom: 12px;
}

.achievements-grid {
grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
gap: 12px;
}

#panel-main-content {
padding: 20px;
line-height: 2.2;
}

#panel-main-content .dialogue-line {
margin: 2em 0;
padding: 14px 18px;
}

#panel-main-content .narrative-text {
margin: 2em 0;
line-height: 2.4;
}

.achievement-notification {
top: 15px;
right: 15px;
left: 15px;
transform: translateY(-120px);
}

.achievement-notification.show {
transform: translateY(0);
}
}

@media (max-width: 480px) {
.nav-bar {
padding: 8px 4px;
}

.nav-button {
padding: 8px 6px;
font-size: 11px;
min-width: 50px;
max-width: 75px;
}

.content-area {
padding: 12px;
