'attr-stamina': { barId: 'bar-stamina', max: 150 },
'skill-lyrics': { barId: 'bar-lyrics', max: 100 },
'skill-composition': { barId: 'bar-composition', max: 100 },
'skill-highpitch': { barId: 'bar-highpitch', max: 100 },
'skill-script': { barId: 'bar-script', max: 100 },
'skill-emotion': { barId: 'bar-emotion', max: 100 },
'skill-improvisation': { barId: 'bar-improvisation', max: 100 }
};

for (const valueId in configs) {
const config = configs[valueId];
const valueElement = el(valueId);
const barElement = el(config.barId);

if (valueElement && barElement) {
const match = valueElement.textContent.match(/-?\d+\.?\d*/);
const numericValue = match ? parseFloat(match[0]) : 0;
let percentage = Math.min(100, Math.max(0, (numericValue / config.max) * 100));

setTimeout(() => {
barElement.style.width = percentage + '%';
}, 100);
}
}
}

