function updateAchievements(data) {
    // 防止在游戏未开始或数据不完整时运行
    if (!data || !data['天数'] || data['天数'] === '--' || parseInt(data['天数'], 10) < 1) {
        return;
    }

    const getStat = (key) => {
        if (!data[key] || data[key] === '--') return 0;
        const match = String(data[key]).match(/-?\d+\.?\d*/);
        return match ? parseInt(match[0], 10) : 0;
    };

    const combinedText = ((data['正文'] || '') + ' ' + (data['事件'] || '')).toLowerCase();
    const checkText = (keywords) => {
        return keywords.some(keyword => combinedText.includes(keyword.toLowerCase()));
    };

    const checkValue = (key, value) => {
        return data[key] && data[key].includes(value);
    }

    // 获取当前属性值
    const stamina = getStat('体力');
    const singing = getStat('唱功');
    const dancing = getStat('舞蹈');
    const intelligence = getStat('才智');
