    const lyrics = getStat('作词');
    const composition = getStat('作曲');
    const highpitch = getStat('高音爆发');
    const script = getStat('剧本理解');
    const emotion = getStat('情绪控制');

    // 检测体力消耗（完美主义者成就）
    if (lastStamina !== null && lastStamina > stamina) {
        const staminaConsumed = lastStamina - stamina;
        if (staminaConsumed > 25) {
            checkAndUnlockAchievement('perfectionist', true);
        }
    }
    lastStamina = stamina;

    // --- 修正后的成就判定逻辑 ---

    // 基于属性值的成就 (这些通常比较安全)
    checkAndUnlockAchievement('trainee_daily', stamina > 0 && stamina < 30);
    checkAndUnlockAchievement('sweat_reward', singing >= 50 || dancing >= 50);
    checkAndUnlockAchievement('talent_first_show', lyrics >= 30 || composition >= 30 || highpitch >= 30 || script >= 30 || emotion >= 30 || improvisation >= 30);
    checkAndUnlockAchievement('language_genius', intelligence >= 70);
    checkAndUnlockAchievement('first_bucket_gold', income >= 1000000);
    checkAndUnlockAchievement('chaebol_life', income >= 100000000);
    checkAndUnlockAchievement('beloved_one', affection >= 100);

    // 基于文本和数值的复合条件成就 (增强鲁棒性)
    checkAndUnlockAchievement('national_mc', improvisation >= 80 && checkText(['主持', 'mc', '综艺']));
    checkAndUnlockAchievement('first_stage', checkText(['初登舞台', '第一次演出', '首次登台', '第一次表演', '初次公演']));

    // **修正**: '一位歌手' - 必须有实际人气，且关键词更明确
    const firstPlaceWon = checkText(['获得一位', '拿下了一位', '获得了第一名', '音乐节目冠军']) && popularity > 10000;
    checkAndUnlockAchievement('first_place_singer', firstPlaceWon);

    // **修正**: '音源KILLER' - 必须有实际人气，关键词更明确
    const chartKillerAchieved = checkText(['空降前三', '音源榜前三', '音源kill', '横扫榜单']) && popularity > 5000;
    checkAndUnlockAchievement('chart_killer', chartKillerAchieved);

    // **修正**: '百万销量' - 必须有可观收入支撑
    const millionSalesAchieved = checkText(['百万销量', '销量突破100万']) && income > 500000;
    checkAndUnlockAchievement('million_sales', millionSalesAchieved);

    // '忠武路新星' - 原逻辑较好，保持AND条件
    const chungmuroStarAchieved = checkText(['电影', '忠武路', '拍摄电影']) && checkText(['好评', '获奖', '成功', '大获成功']);
    checkAndUnlockAchievement('chungmuro_star', chungmuroStarAchieved);

    // **修正**: '格莱美' - 必须有极高人气和明确的获奖/提名动作
    const grammyAchieved = checkText(['格莱美', 'grammy', '国际音乐奖']) && checkText(['提名', '获奖']) && popularity > 500000;
    checkAndUnlockAchievement('grammy_echo', grammyAchieved);

    // **修正**: '江南Style' - 必须有高收入，且明确搬入高档住宅
    const movedToLuxury = checkText(['搬入', '搬进', '搬到了']) && checkText(['高档公寓', '江南区', '豪华公寓', '豪宅']) && income > 3000000;
    checkAndUnlockAchievement('gangnam_style', movedToLuxury);

    // '慈善之心' - 捐款需要有足够的钱
    const charityAchieved = checkText(['慈善', '捐款', '公益']) && checkText(['100万', '百万']) && income > 1500000;
    checkAndUnlockAchievement('charity_heart', charityAchieved);

    // 基于特定事件文本的成就 (这些通常比较安全)
    checkAndUnlockAchievement('firm_choice', checkText(['酒局的邀请', '拒绝酒局', '保护了阿狸']));
    checkAndUnlockAchievement('opinion_leader', checkText(['舆论反转', '风向转变', '扭转舆论', '舆论逆转']));
    checkAndUnlockAchievement('crown_choice', checkText(['王冠的邀约', '王冠邀约']));

    // 基于特定值的成就 (这些是安全的)
    checkAndUnlockAchievement('money_printer', checkValue('代言等级', '国际奢侈品'));
    checkAndUnlockAchievement('crossover_queen', checkValue('圈内地位', '跨界天后'));
    checkAndUnlockAchievement('only_god', checkValue('圈内地位', '唯一真神'));
}


function checkAndUnlockAchievement(achievementId, condition) {
    if (!condition || unlockedAchievements.has(achievementId)) {
        return;
    }

    const card = el(`achievement-${achievementId}`);
    if (card && !card.classList.contains('unlocked')) {
        card.classList.add('unlocked');
        unlockedAchievements.add(achievementId);
        showAchievementNotification(achievementsData.find(a => a.id === achievementId));
    }
}

function showAchievementNotification(achievement) {
if (!achievement) return;
const notification = el('achievement-notification');
const notificationText = el('achievement-notification-text');
notificationText.textContent = `🏆 解锁新成就：${achievement.name}！`;
notification.classList.add('show');
setTimeout(() => {
notification.classList.remove('show');
}, 3000);
}

function showPanel(panelId, clickedButton) {
document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
document.querySelectorAll('.nav-button').forEach(b => b.classList.remove('active'));

el(panelId).classList.add('active');
if (clickedButton) clickedButton.classList.add('active');

if (panelId.includes('panel-attributes') || panelId.includes('panel-skills') || panelId.includes('panel-variables')) {
setTimeout(updateProgressBars, 100);
}
}

function selectOption(text) {
try {
const cleanText = text.replace(/^\[.*?\]\s*/, '').trim();

const selectors = [
'#send_textarea',
'textarea[placeholder*="消息"]',
'textarea[placeholder*="发送"]',
'textarea[placeholder*="输入"]',
'textarea[placeholder*="Send"]',
'textarea[placeholder*="message"]',
'textarea[placeholder*="chat"]',
'#user-input',
'.textarea',
'textarea'
];

let textarea = null;
for (const selector of selectors) {
try {
textarea = window.parent.document.querySelector(selector) || document.querySelector(selector);
if (textarea) break;
} catch (e) {
continue;
}
}

if (textarea) {
textarea.value = cleanText;
textarea.focus();

const events = ['input', 'change', 'keyup'];
events.forEach(eventType => {
textarea.dispatchEvent(new Event(eventType, { bubbles: true }));
});

const sendSelectors = [
'#send_but',
'#send-button',
'button[title*="发送"]',
'button[title*="Send"]',
'button[type="submit"]',
'.send-button',
'button:contains("发送")',
'button:contains("Send")'
];

let sendButton = null;
for (const selector of sendSelectors) {
try {
sendButton = window.parent.document.querySelector(selector) || document.querySelector(selector);
if (sendButton) break;
} catch (e) {
continue;
}
}

if (sendButton) {
setTimeout(() => sendButton.click(), 100);
} else {
setTimeout(() => {
const enterEvent = new KeyboardEvent('keydown', {
key: 'Enter',
code: 'Enter',
keyCode: 13,
which: 13,
bubbles: true
});
textarea.dispatchEvent(enterEvent);
}, 100);
}

console.log('选项已发送:', cleanText);
} else {
console.warn('找不到输入框');
if (navigator.clipboard) {
navigator.clipboard.writeText(cleanText).then(() => {
alert('选项已复制到剪贴板，请手动粘贴发送');
});
}
}
} catch (e) {
console.error("发送选项时出错:", e);
if (navigator.clipboard) {
navigator.clipboard.writeText(text).then(() => {
alert('自动发送失败，选项已复制到剪贴板');
});
}
}
}

function processAndRefresh() {
const rawDataContainer = el('ai-data-container');
if (!rawDataContainer) return;

const rawData = rawDataContainer.textContent || "";
const parsedData = parseAIData(rawData);

console.log("Parsed Data:", parsedData);

updateUIFromData(parsedData);
}

document.addEventListener('DOMContentLoaded', () => {
initializeAchievements();

const aiDataContainer = el('ai-data-container');
if (aiDataContainer) {
const observer = new MutationObserver(() => {
processAndRefresh();
});
observer.observe(aiDataContainer, { childList: true, characterData: true, subtree: true });
}

processAndRefresh();
showPanel('panel-main', document.querySelector('.nav-button'));
});
</script>

</body>
</html>
