      "情绪控制": [5, "取值范围[0, 100]。【演技特训】和【心理辅导】可提升[+2~+6]。是冲击【国际影后】的核心。"],
      "即兴反应": [8, "取值范围[0, 100]。参与【综艺节目】可提升[+1~+4]。是成为【国民MC】的必备素质。"]
    }
  }
}

entries.content:
---
<!--
  模块一：每日结算、生活环境判定 与 动态开销系统
  核心逻辑：此模块为常驻（蓝灯），在每次AI回应前运行。它会根据阿狸的地位和收入，首先输出当前的生活环境描述，这个描述将作为模块二事件触发的“钥匙”。然后，它会自动计算并扣除每日开销，实现生存压力。
-->
<%_
  // 确保 context 对象存在，如果不存在则创建一个本地的替代品
  if (typeof context === 'undefined') {
    const local_context_store = new Map();
    var context = {
      get: (key) => local_context_store.get(key),
      set: (key, value) => local_context_store.set(key, value)
    };
  }

  const income = getvar('stat_data.阿狸.状态.收入[0]');
  const standing = getvar('stat_data.阿狸.状态.圈内地位[0]');
  const day = getvar('stat_data.世界.状态.天数[0]');
  let daily_cost = 0;
  let living_status_text = '';

  if (income !== undefined && standing !== undefined) {
    if (standing === '无名新人' || income < 500000) {
      daily_cost = 5000;
      living_status_text = `[生活环境：一间位于城市边缘的半地下室，空气中混合着潮湿的霉味。为了省钱，阿狸大部分时间都只能吃泡面和打折便当，唯一的娱乐就是用那台老旧的笔记本电脑看电影。]`;
    } else if (standing === '潜力新秀' || income < 2000000) {
      daily_cost = 20000;
      living_status_text = `[生活环境：位于市中心的合租公寓，虽然有了独立的卧室，但还是要和别人共用狭窄的厨房和卫生间。阿狸学会了在嘈杂的环境中戴上耳机，专注于自己的音乐世界。]`;
    } else if (standing === '人气偶像' || income < 10000000) {
      daily_cost = 100000;
      living_status_text = `[生活环境：一处高档酒店式公寓，安保严密，隔绝了大部分骚扰。公寓自带的健身房和24小时餐饮服务，让阿狸的生活品质有了质的飞跃，她终于可以不用担心饮食和安全，专心搞事业。]`;
    } else if (standing === '一线女星' || income < 100000000) {
      daily_cost = 500000;
      living_status_text = `[生活环境：坐落于山顶富人区的独栋豪华别墅，配备了私人录音室和家庭影院，让她可以随时迸发灵感并立刻实践。车库里停放着<user>为她挑选的跑车，让她可以自由地去任何想去的地方。]`;
    } else if (standing === '全球天后') {
      daily_cost = 2000000;
      living_status_text = `[生活环境：一座位于热带的私人海岛，<user>就是这座岛屿的另一位主人。私人飞机可以接送他们往返于世界各地。在这里，阿狸可以完全卸下防备，享受只属于她和<user>的宁静时光。]`;
    }

    // 步骤一：首先，无条件输出生活环境描述
    template.ops.push(living_status_text);

    // 步骤二：接着，处理每日开销的扣除逻辑
    const last_day = context.get('last_day_processed') || -1;
    if (day !== undefined && day > last_day) {
      const update_command = `_.set('阿狸.状态.收入', ${income}, ${income - daily_cost}); // 每日生活成本结算`;
      const update_analysis = `阿狸.状态.收入: Yes`;

      let update_block = template.findBlock('UpdateVariable');
      if (!update_block) {
        update_block = template.createBlock('UpdateVariable');
        update_block.appendChild(template.createBlock('Analysis'));
        template.ops.push(update_block);
      }

      if(update_block.findBlock('Analysis')) {
        update_block.findBlock('Analysis').push(update_analysis);
      }
      update_block.push(update_command);

      // 将已处理的天数存入上下文，防止重复扣款
      context.set('last_day_processed', day);
    }
  }
_%>

<!--
  模块二：情景化随机事件池
  核心逻辑：此模块紧随模块一运行。它会扫描模块一刚刚输出的`生活环境`文本，只有当环境描述匹配时，对应地位的事件池才会被激活。触发概率为35%。此模块的运行独立于用户指令。
-->
<%_
  const last_response_for_regex = context.get('last_response_for_regex') || '';
  // 检查 last_user_message 是否包含付费活动关键词，如果不包含，才执行随机事件逻辑
  const user_msg = getvar('last_user_message') || '';
  const is_paid_action = ['声乐课程', '舞蹈集训', '演技特训', '形象设计', '语言学习', '心理辅导', '创作指导', '人脉拓展', '粉丝运营', '危机公关'].some(keyword => user_msg.includes(keyword));

  if (!is_paid_action && getvar('stat_data.阿狸.状态.圈内地位[0]') !== undefined && Math.random() < 0.35) {
    const standing_status = getvar('stat_data.阿狸.状态.圈内地位[0]');

    // 无名新人的事件
    if (standing_status === '无名新人' && last_response_for_regex.includes('半地下室')) {
      const eventRoll = Math.random();
      if (eventRoll < 0.25) {
_%>
[正面事件：意外的赏识] 在一次小型音乐节的演出后，一位路过的、半退隐的金牌音乐制作人注意到了阿狸独特的声线。他通过后台找到了疲惫的阿狸，递给她一张名片，说很欣赏她的潜力，愿意免费为她制作一首单曲。这张小小的卡片，或许是通往天堂的阶梯。他等待着<user>的回应。
<%_
      } else if (eventRoll < 0.50) {
_%>
[负面事件：酒局的邀请] 公司的前辈（非<user>的直接上司）传来消息，说一位能决定新人命运的电视台高层制作人“点名”要见阿狸。他将一张冰冷的酒店房卡塞进<user>手里，用只有两人能听到的声音说：“这是你们唯一的机会，是继续烂在这里，还是抓住机会，你自己选”。阿狸在旁边听得一清二楚，她的身体僵硬，看向<user>的眼神充满了恐惧和无助。
<%_
      } else if (eventRoll < 0.75) {
_%>
[负面事件：试镜的代价] <user>好不容易为阿狸争取到一个网络剧的小角色试镜机会。但在只有她和导演两人的房间里，导演的要求却越来越过分，从让她模拟亲热戏，到要求她脱下外套“更好地看身材线条”。他的手甚至开始不规矩地在阿狸的腰间游走，并暗示这只是“演员的基本素养”。阿狸僵在原地，不知所措，只能用求助的目光看向陪同前来的<user>。
<%_
      } else {
_%>
[负面事件：前辈的打压] 在一个拼盘演唱会的后台共用化妆间，一位当红的前辈偶像故意“不小心”将一杯滚烫的咖啡洒在了阿狸唯一的演出服上，并轻蔑地嘲讽她“新人就该有新人的样子，别总想着出风头”。距离上场只剩十分钟，而那件湿透的、带着污渍的衣服是她唯一的选择。
<%_
      }
    }
    // 潜力新秀的事件
    else if (standing_status === '潜力新秀' && last_response_for_regex.includes('合租公寓')) {
      const eventRoll = Math.random();
      if (eventRoll < 0.33) {
_%>
[正面事件：贵人相助] 在一次时尚晚宴上，阿狸因为耿直的发言得罪了一位时尚杂志的主编，眼看就要被行业封杀。但同场的一位德高望重的老牌影后却站出来为她解围，并公开表示欣赏她的性格。这位影后私下约见了阿狸，表示愿意将她引荐给自己的人脉圈。
<%_
      } else if (eventRoll < 0.66) {
_%>
[负面事件：对赌的筹码] 一位在圈内非常有权势的富豪，也是阿狸下一张专辑的最大投资人，在一次私人派对上，公开表示很“欣赏”阿狸。他向<user>提出了一个对赌协议：如果<user>能“说服”阿狸陪他出海游玩三天，他将追加三倍的投资，并保证阿狸拿下所有年末大奖。如果拒绝，他将立刻撤资并动用关系封杀阿狸。他笑着看着<user>，仿佛在欣赏一场有趣的戏剧。
<%_
      } else {
_%>
[负面事件：赞助商的要求] 阿狸接到一个重要的运动品牌代言，但该品牌的CEO是个出了名的花花公子。在拍摄广告期间，他以“指导动作”为名，对穿着紧身运动服的阿狸进行各种不必要的身体接触，甚至在晚上发来信息，用暧昧的语言邀请她去酒店房间“单独聊聊后续的合作细节”。
<%_
      }
    }
    // 一线女星的事件
    else if (standing_status === '一线女星' && (last_response_for_regex.includes('酒店式公寓') || last_response_for_regex.includes('豪华别墅'))) {
      const eventRoll = Math.random();
      if (eventRoll < 0.33) {
_%>
[正面事件：时尚圈的王座] 法国巴黎，Vogue总部的顶层办公室内，时尚界的女魔头主编亲自为阿狸端上一杯咖啡。她宣布，将推掉原定的好莱坞巨星，让阿狸成为下一期“金九”特刊的单人封面人物，这是时尚圈最高荣誉的象征。她希望<user>能让阿狸拿出一个独一无二的时尚概念，来震撼全球。
<%_
      } else if (eventRoll < 0.66) {
_%>
[影响力事件：点石成金] 阿狸在一次机场街拍中，无意间佩戴了一个小众设计师品牌的耳环。照片发布后24小时内，该品牌官网所有商品全部售罄，品牌价值一夜之间暴涨三倍。该设计师激动地联系<user>，希望阿狸能成为品牌合伙人，他愿意出让30%的股份，只为换取阿狸的长期绑定。
<%_
      } else {
_%>
[危机事件：税务风波] 国际调查记者联盟曝光了一份涉及全球名人的避税文件，阿狸的名字赫然在列（尽管这可能是其前经纪公司的操作）。一时间全球舆论哗然，各大合作品牌方纷纷发来问询函，要求<user>在48小时内给出合理解释，否则将面临天价索赔。预计潜在损失高达5000万元。
<%_
      }
    }
    // 全球天后的事件
    else if (standing_status === '全球天后' && last_response_for_regex.includes('私人海岛')) {
      const eventRoll = Math.random();
      if (eventRoll < 0.33) {
_%>
[全球影响力事件：改变规则] 世界音乐大奖的主办方，因为一项歧视性的评选规则而遭到舆论抵制。主办方主席亲自飞到阿狸所在的私人海岛，恳求阿狸出面发声支持他们。这意味着，阿狸的一句话，可以决定这个百年奖项的生死存亡。她看向<user>，是要拯救它，还是让它成为历史，全凭<user>定夺。
<%_
      } else if (eventRoll < 0.66) {
_%>
[全球影响力事件：资本的追随] 华尔街一家顶级的投资银行向<user>发来报告，分析指出，凡是阿狸代言的品牌，其股价在未来一年内平均上涨15%。他们提议与阿狸成立一支专项时尚投资基金，由阿狸来决定投资方向，他们负责提供无限的资金。这不仅是收入，更是真正掌控一个行业的力量。
<%_
      } else {
_%>
[终极事件：王冠的邀约] 阿狸的魅力已经超越了娱乐的范畴，成为了地缘政治中不可忽视的软实力。数封带有国徽火漆印的信函，通过最机密的外交渠道，同时送到了<user>的办公桌上。
- 来自中东某石油王国的年轻王储，承诺为阿狸建造一座现实中的童话城堡，并奉上王后桂冠与国家一半的文化基金支配权。
- 来自欧洲某古老王室的国王陛下，邀请阿狸成为他的王妃，并许诺她将获得整个欧洲上流社会的无上荣光与历史地位。
- 来自某个超级大国的总统，他并不提供头衔，而是暗示<user>，若阿狸愿意成为该国的“文化大使”与总统的“特殊挚友”，他将推动一项足以改变全球贸易格局的法案，该法案的受益方<user>可以指定。
他们都在等待<user>和阿狸的抉择。这个选择，将不再仅仅关乎阿狸的个人幸福，而是会在世界地图上，引发一连串难以预料的连锁反应。
<%_
      }
    }
  }
_%>

<!--
  模块三：动态周记系统
  核心逻辑：此模块会在每周的最后一天（天数是7的倍数时）触发。它会综合判断阿狸的多种状态，生成一段符合她当前心境的日记。
-->
<%_
  const current_day_diary = getvar('stat_data.世界.状态.天数[0]');
  if (current_day_diary !== undefined && current_day_diary > 0 && current_day_diary % 7 === 0) {
    const health = getvar('stat_data.阿狸.状态.健康状况[0]');
    const pressure = getvar('stat_data.阿狸.状态.压力值[0]');
    const love = getvar('stat_data.阿狸.状态.对<user>好感度[0]');
    const current_income_diary = getvar('stat_data.阿狸.状态.收入[0]');
_%>
[偶像日记 - 第【[getval:<%= Math.floor(current_day_diary / 7) %>]】周]
<%_
    if (pressure > 70 && health !== '良好') {
_%>
这一周过的像一场噩梦。身体的警报和外界的压力快要把我压垮了。有时候真想放弃一切，躲起来再也不见人。但只要想到<user>还在身边，我又会生出一点点坚持下去的勇气。我到底，还能撑多久。
<%_
    } else if (current_income_diary < 100000 && love > 80) {
_%>
虽然每天都在为账单发愁，住在不算宽敞的地方，但这一周我却觉得很幸福。因为每天都能看到<user>，能和他一起吃便利店买来的晚餐，看着同一部电影。有他在，再苦的日子似乎都泛着甜味。我们会好起来的，一定会的。
<%_
    } else if (getvar('stat_data.阿狸.状态.圈内地位[0]') === '一线女星' && pressure > 50) {
_%>
一周又结束了。行程表上密密麻麻的字，银行账户里不断增长的数字，这一切都像一个华丽的牢笼。我得到了很多人梦寐以求的东西，却好像失去了最简单的快乐。只有在夜深人静，和<user>通电话时，我才能感觉到自己还是一个活生生的人。
<%_
    } else {
_%>
又是充实的一周！感觉自己又进步了不少。最近在练习室里找到了一点新的感觉，希望能在下次的舞台上给<user>和粉丝们一个惊喜。有<user>在，我什么都不怕。未来，我们一起走下去吧。
<%_
    }
_%>
[阿狸发布了一条新的社交媒体动态]
“一周结束啦！感谢大家的支持，也谢谢一直陪在我身边的某人❤️。下周继续加油！#AHRI #感恩”
<%_
  }
_%>

<!--
  模块四：付费活动处理器
  核心逻辑：此模块专用于处理用户发起的付费活动。它会检查用户最新消息是否包含特定关键词，并进行费用检查。只有费用足够时，才会执行活动并更新变量。
-->
<%_
  const last_user_message = getvar('last_user_message') || '';
  const current_income_action = getvar('stat_data.阿狸.状态.收入[0]');
  let cost = 0;
  let action_name = '';
  let updates = [];
  let analyses = [];

  // 定义所有付费活动及其成本和效果
  const actions = {
    '声乐课程': { cost: 500000, updates: ["_.set('阿狸.属性.唱功', " + getvar('stat_data.阿狸.属性.唱功[0]') + ", " + (getvar('stat_data.阿狸.属性.唱功[0]') + Math.floor(Math.random() * 5) + 3) + "); // +3~+7", "_.set('阿狸.属性.体力', " + getvar('stat_data.阿狸.属性.体力[0]') + ", " + (getvar('stat_data.阿狸.属性.体力[0]') - 10) + ");"], analyses: ['阿狸.属性.唱功: Yes', '阿狸.属性.体力: Yes'] },
    '舞蹈集训': { cost: 1500000, updates: ["_.set('阿狸.属性.舞蹈', " + getvar('stat_data.阿狸.属性.舞蹈[0]') + ", " + (getvar('stat_data.阿狸.属性.舞蹈[0]') + Math.floor(Math.random() * 5) + 4) + "); // +4~+8", "_.set('阿狸.属性.体力', " + getvar('stat_data.阿狸.属性.体力[0]') + ", " + (getvar('stat_data.阿狸.属性.体力[0]') - 15) + ");"], analyses: ['阿狸.属性.舞蹈: Yes', '阿狸.属性.体力: Yes'] },
    '演技特训': { cost: 800000, updates: ["_.set('阿狸.技能.剧本理解', " + getvar('stat_data.阿狸.技能.剧本理解[0]') + ", " + (getvar('stat_data.阿狸.技能.剧本理解[0]') + Math.floor(Math.random() * 6) + 5) + "); // +5~+10", "_.set('阿狸.技能.情绪控制', " + getvar('stat_data.阿狸.技能.情绪控制[0]') + ", " + (getvar('stat_data.阿狸.技能.情绪控制[0]') + Math.floor(Math.random() * 5) + 4) + "); // +4~+8", "_.set('阿狸.属性.体力', " + getvar('stat_data.阿狸.属性.体力[0]') + ", " + (getvar('stat_data.阿狸.属性.体力[0]') - 10) + ");"], analyses: ['阿狸.技能.剧本理解: Yes', '阿狸.技能.情绪控制: Yes', '阿狸.属性.体力: Yes'] },
    '形象设计': { cost: 2000000, updates: ["_.set('阿狸.属性.颜值', " + getvar('stat_data.阿狸.属性.颜值[0]') + ", " + (getvar('stat_data.阿狸.属性.颜值[0]') + Math.floor(Math.random() * 2) + 1) + "); // +1~+2", "_.set('阿狸.属性.魅力', " + getvar('stat_data.阿狸.属性.魅力[0]') + ", " + (getvar('stat_data.阿狸.属性.魅力[0]') + Math.floor(Math.random() * 3) + 3) + "); // +3~+5"], analyses: ['阿狸.属性.颜值: Yes', '阿狸.属性.魅力: Yes'] },
    '语言学习': { cost: 200000, updates: ["_.set('阿狸.属性.才智', " + getvar('stat_data.阿狸.属性.才智[0]') + ", " + (getvar('stat_data.阿狸.属性.才智[0]') + Math.floor(Math.random() * 3) + 2) + "); // +2~+4", "_.set('阿狸.属性.体力', " + getvar('stat_data.阿狸.属性.体力[0]') + ", " + (getvar('stat_data.阿狸.属性.体力[0]') - 5) + ");"], analyses: ['阿狸.属性.才智: Yes', '阿狸.属性.体力: Yes'] },
    '心理辅导': { cost: 900000, updates: ["_.set('阿狸.状态.压力值', " + getvar('stat_data.阿狸.状态.压力值[0]') + ", " + (getvar('stat_data.阿狸.状态.压力值[0]') - (Math.floor(Math.random() * 16) + 15)) + "); // -15~-30", "_.set('阿狸.状态.精神状态', " + getvar('stat_data.阿狸.状态.精神状态[0]') + ", " + (getvar('stat_data.阿狸.状态.精神状态[0]') + Math.floor(Math.random() * 16) + 10) + "); // +10~+25"], analyses: ['阿狸.状态.压力值: Yes', '阿狸.状态.精神状态: Yes'] },
    '创作指导': { cost: 3000000, updates: ["_.set('阿狸.技能.作词', " + getvar('stat_data.阿狸.技能.作词[0]') + ", " + (getvar('stat_data.阿狸.技能.作词[0]') + Math.floor(Math.random() * 6) + 5) + "); // +5~+10", "_.set('阿狸.技能.作曲', " + getvar('stat_data.阿狸.技能.作曲[0]') + ", " + (getvar('stat_data.阿狸.技能.作曲[0]') + Math.floor(Math.random() * 6) + 5) + "); // +5~+10", "_.set('阿狸.属性.体力', " + getvar('stat_data.阿狸.属性.体力[0]') + ", " + (getvar('stat_data.阿狸.属性.体力[0]') - 20) + ");"], analyses: ['阿狸.技能.作词: Yes', '阿狸.技能.作曲: Yes', '阿狸.属性.体力: Yes'] }
  };

  // 检查是否有付费活动被触发
  for (const [name, details] of Object.entries(actions)) {
    if (last_user_message.includes(name)) {
      action_name = name;
      cost = details.cost;
      updates = details.updates;
      analyses = details.analyses;
      break;
    }
  }

  // 如果触发了付费活动
  if (action_name) {
    // 费用检查
    if (current_income_action >= cost) {
      // 费用足够，执行更新
      template.ops.push(`[系统提示：已成功安排【${action_name}】，消费 ${cost} 韩元。]`);
      let update_block = template.findBlock('UpdateVariable');
      if (!update_block) {
        update_block = template.createBlock('UpdateVariable');
        update_block.appendChild(template.createBlock('Analysis'));
        template.ops.push(update_block);
      }

      const analysis_block = update_block.findBlock('Analysis');
      if (analysis_block) {
        analyses.forEach(a => analysis_block.push(a));
        analysis_block.push('阿狸.状态.收入: Yes');
      }

      updates.forEach(u => update_block.push(u));
      update_block.push(`_.set('阿狸.状态.收入', ${current_income_action}, ${current_income_action - cost}); // 支付活动费用`);

    } else {
      // 费用不足，拒绝并提醒
      template.ops.push(`[系统提示：账户余额不足！无法安排【${action_name}】。 所需费用：${cost}，当前余额：${current_income_action}]`);
    }
  }
_%>

