---
<!--
  模块一：每日结算、生活环境判定 与 动态开销系统
  核心逻辑：此模块为常驻（蓝灯），在每次AI回应前运行。它会根据阿狸的地位和收入，首先输出当前的生活环境描述，这个描述将作为模块二事件触发的“钥匙”。然后，它会自动计算并扣除每日开销，实现生存压力。
-->
<%_
  // 确保 context 对象存在，如果不存在则创建一个本地的替代品
  if (typeof context === 'undefined') {
    const local_context_store = new Map();
    var context = {
      get: (key) => local_context_store.get(key),
      set: (key, value) => local_context_store.set(key, value)
    };
  }

  const income = getvar('stat_data.阿狸.状态.收入[0]');
  const standing = getvar('stat_data.阿狸.状态.圈内地位[0]');
  const day = getvar('stat_data.世界.状态.天数[0]');
  let daily_cost = 0;
  let living_status_text = '';

  if (income !== undefined && standing !== undefined) {
    if (standing === '无名新人' || income < 500000) {
      daily_cost = 5000;
      living_status_text = `[生活环境：一间位于城市边缘的半地下室，空气中混合着潮湿的霉味。为了省钱，阿狸大部分时间都只能吃泡面和打折便当，唯一的娱乐就是用那台老旧的笔记本电脑看电影。]`;
    } else if (standing === '潜力新秀' || income < 2000000) {
      daily_cost = 20000;
      living_status_text = `[生活环境：位于市中心的合租公寓，虽然有了独立的卧室，但还是要和别人共用狭窄的厨房和卫生间。阿狸学会了在嘈杂的环境中戴上耳机，专注于自己的音乐世界。]`;
    } else if (standing === '人气偶像' || income < 10000000) {
      daily_cost = 100000;
      living_status_text = `[生活环境：一处高档酒店式公寓，安保严密，隔绝了大部分骚扰。公寓自带的健身房和24小时餐饮服务，让阿狸的生活品质有了质的飞跃，她终于可以不用担心饮食和安全，专心搞事业。]`;
    } else if (standing === '一线女星' || income < 100000000) {
      daily_cost = 500000;
      living_status_text = `[生活环境：坐落于山顶富人区的独栋豪华别墅，配备了私人录音室和家庭影院，让她可以随时迸发灵感并立刻实践。车库里停放着<user>为她挑选的跑车，让她可以自由地去任何想去的地方。]`;
    } else if (standing === '全球天后') {
      daily_cost = 2000000;
      living_status_text = `[生活环境：一座位于热带的私人海岛，<user>就是这座岛屿的另一位主人。私人飞机可以接送他们往返于世界各地。在这里，阿狸可以完全卸下防备，享受只属于她和<user>的宁静时光。]`;
    }

    // 步骤一：首先，无条件输出生活环境描述
    template.ops.push(living_status_text);

    // 步骤二：接着，处理每日开销的扣除逻辑
    const last_day = context.get('last_day_processed') || -1;
    if (day !== undefined && day > last_day) {
      const update_command = `_.set('阿狸.状态.收入', ${income}, ${income - daily_cost}); // 每日生活成本结算`;
      const update_analysis = `阿狸.状态.收入: Yes`;

      let update_block = template.findBlock('UpdateVariable');
      if (!update_block) {
        update_block = template.createBlock('UpdateVariable');
        update_block.appendChild(template.createBlock('Analysis'));
        template.ops.push(update_block);
      }

      if(update_block.findBlock('Analysis')) {
        update_block.findBlock('Analysis').push(update_analysis);
      }
      update_block.push(update_command);

      // 将已处理的天数存入上下文，防止重复扣款
      context.set('last_day_processed', day);
    }
  }
_%>

<!--
